@implementation TFAITestResults
- (void)viewDidLoad{[super viewDidLoad];self.title=@"连接能力测试";self.results=[self.connection[@"testResults"] mutableCopy]?:[NSMutableDictionary new];self.navigationItem.rightBarButtonItem=AIBar(@"play.fill",@"一键测试",self,@selector(startTests));self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=72;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return 5;}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return @"测试仅发送内置样例，不携带项目、对话或附件。图片、流式和工具分别验证，可能产生少量 API 用量；工具测试不执行本机操作。失败不代表永久不支持，请查看具体原因。";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{if(i.row==0)return AICell(self.connection[@"name"]?:@"当前连接",[NSString stringWithFormat:@"%@\n%@",self.connection[@"model"]?:@"未选择模型",self.connection[@"baseURL"]?:@""],@"network");NSString *key=@[@"text",@"stream",@"image",@"tools"][i.row-1];NSDictionary *r=self.results[key];NSString *state=r[@"state"]?:@"pending";BOOL pass=[state isEqual:@"pass"],fail=[state isEqual:@"fail"],unknown=[state isEqual:@"unknown"],active=[state isEqual:@"running"];NSString *title=[NSString stringWithFormat:@"%@ %@",pass?@"✅":fail?@"❌":unknown?@"⚠️":active?@"◌":@"○",@[@"文本响应",@"流式响应",@"图片理解",@"工具调用"][i.row-1]];UITableViewCell *c=AICell(title,r[@"detail"]?:@"等待测试",pass?@"checkmark.circle.fill":fail?@"xmark.circle.fill":@"circle");c.imageView.tintColor=pass?UIColor.systemGreenColor:fail?UIColor.systemRedColor:unknown?UIColor.systemOrangeColor:UIColor.secondaryLabelColor;c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];if(!self.running)self.results=[self.connection[@"testResults"] mutableCopy]?:[NSMutableDictionary new];[self.tableView reloadData];}
- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)indexPath{[tableView deselectRowAtIndexPath:indexPath animated:YES];if(indexPath.row==0)return;NSString *capability=@[@"text",@"stream",@"image",@"tools"][indexPath.row-1];UIViewController *detail=TFAITestDetailController(self.connection,capability,self.results[capability],!self.running);[self.navigationController pushViewController:detail animated:YES];}
- (void)startTests{if(self.running)return;if(![self.connection[@"model"] length]){AIAlert(self,@"请先选择模型",@"在连接设置中填写模型 ID 后再测试。");return;}self.running=YES;self.step=0;[self.results removeAllObjects];self.navigationItem.rightBarButtonItem.enabled=NO;[self nextTest];}
- (void)nextTest{if(!self.running)return;if(self.step==4){self.running=NO;self.navigationItem.rightBarButtonItem.enabled=YES;return;}NSString *key=@[@"text",@"stream",@"image",@"tools"][self.step];self.results[key]=@{@"state":@"running",@"detail":@"正在验证…"};[self.tableView reloadData];self.transport=[TFAITransport new];__weak typeof(self) weak=self;[self.transport probe:[self.connection copy] capability:key completion:^(NSDictionary *result,NSError *error){TFAITestResults *s=weak;if(!s||!s.running)return;s.results[key]=TFAIRecordProbeResult(s.connection,key,result,error);[s.tableView reloadData];s.step++;[s nextTest];}];}
- (void)viewDidDisappear:(BOOL)animated{[super viewDidDisappear:animated];if(self.isMovingFromParentViewController){self.running=NO;[self.transport cancel];}}
@end

