 else {title=@[@"实际请求地址",@"测试文本",@"测试流式",@"测试图片",@"测试工具"][i.row];NSString *suffix=[c[@"protocol"] isEqual:@"responses"]?@"responses":[c[@"protocol"] isEqual:@"anthropic"]?@"messages":@"chat/completions";detail=i.row==0?[NSString stringWithFormat:@"%@/%@",[c[@"baseURL"] stringByTrimmingCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"/"]],suffix]:(c[@"capabilities"][@[@"",@"text",@"stream",@"image",@"tools"][i.row]]?:@"尚未验证");if(![detail isKindOfClass:NSString.class])detail=[detail description];detail=@{@"supported":@"本次验证通过",@"unknown":@"尚未证实支持",@"unsupported":@"不支持"}[detail]?:detail;icon=i.row==0?@"arrow.up.forward.app":@"checkmark.shield";}
