 [t deselectRowAtIndexPath:i animated:YES];if(self.busy||(i.section==0&&i.row==5))return;__weak typeof(self) weak=self;if(i.section==2){TFAITestResults *v=[[TFAITestResults alloc]initWithStyle:UITableViewStyleInsetGrouped];v.connection=self.connection;[self.navigationController pushViewController:v animated:YES];return;}
 if(i.section==0&&i.row==1){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"服务与协议" message:@"Gemini 使用原生协议；DeepSeek 等兼容服务使用对应预设。中转服务请选择它实际提供的协议。切换不会覆盖自定义地址。" preferredStyle:UIAlertControllerStyleActionSheet];for(NSDictionary *entry in TFAIProtocolCatalog()){NSString *p=entry[@"id"];[a addAction:[UIAlertAction actionWithTitle:entry[@"name"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){if([weak.connection[@"protocol"] isEqual:p])return;NSString *oldDefault=nil;for(NSDictionary *old in TFAIProtocolCatalog())if([old[@"id"] isEqual:weak.connection[@"protocol"]])oldDefault=old[@"baseURL"];NSString *base=weak.connection[@"baseURL"];if(!base.length||[base isEqual:oldDefault])weak.connection[@"baseURL"]=entry[@"baseURL"]?:base;weak.connection[@"protocol"]=p;[weak.connection removeObjectForKey:@"capabilities"];[weak.connection removeObjectForKey:@"testResults"];[weak.connection removeObjectForKey:@"models"];weak.connection[@"model"]=@"";[weak persist:nil];}]];}[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];[self presentViewController:a animated:YES completion:nil];return;}

