- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i {
 if(i.section==3){[t deselectRowAtIndexPath:i animated:YES];return;}
 [t deselectRowAtIndexPath:i animated:YES];if(i.section==2){[self.navigationController pushViewController:TFAIWebSettingsController() animated:YES];return;}if(i.section==0){if(self.projectID){[TFAIConnections setConnection:nil project:self.projectID];[t reloadData];}return;}if(!self.connections.count){[self addConnection];return;}
 NSDictionary *c=self.connections[i.row];UIAlertController *a=[UIAlertController alertControllerWithTitle:c[@"name"] message:c[@"baseURL"] preferredStyle:UIAlertControllerStyleActionSheet];[a addAction:[UIAlertAction actionWithTitle:self.projectID?@"用于此项目":@"设为全局默认" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[TFAIConnections setConnection:c[@"id"] project:self.projectID];[t reloadData];}]];[a addAction:[UIAlertAction actionWithTitle:@"编辑连接与测试" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){TFAIConnectionEditor *v=[[TFAIConnectionEditor alloc]initWithStyle:UITableViewStyleInsetGrouped];v.connection=[c mutableCopy];[self.navigationController pushViewController:v animated:YES];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];[self presentViewController:a animated:YES completion:nil];
}
- (void)addConnection{NSMutableDictionary *c=[@{@"id":NSUUID.UUID.UUIDString,@"name":@"新连接",@"protocol":@"chat",@"baseURL":@"https://api.openai.com/v1",@"model":@"",@"models":@[]} mutableCopy];NSError *e=nil;if(![TFAIConnections save:c secret:nil error:&e]){AIAlert(self,@"添加失败",e.localizedDescription);return;}TFAIConnectionEditor *v=[[TFAIConnectionEditor alloc]initWithStyle:UITableViewStyleInsetGrouped];v.connection=c;[self.navigationController pushViewController:v animated:YES];}
@end
UIViewController *TFAISettingsController(NSString *projectID){TFAISettings *v=[[TFAISettings alloc]initWithStyle:UITableViewStyleInsetGrouped];v.projectID=projectID;return v;}
